'use strict';
// agents/index/ is a GENERATED map of the code (agents/tools/build-index.mjs → `npm run agents:index`): symbol → line,
// event → emitters, storage key → readers … so a reader can open a 14,000-line file at the right line. A map that has
// is missing or malformed costs more than no map, so this suite fails on THAT: every file is there
// and carries its "Generated by … from <commit>" header, there is a symbols file for every script, and ten well-known
// symbols are LISTED with a line number. Whether those lines are still exact is ADVISORY (one log line, never a failure):
// a drifted index still lands a reader in the right neighbourhood, and `npm run agents:check` is the strict check.
// Drift in the other index files (events, storage keys, API calls, ids …) is `npm run agents:check`'s business — and
// nothing runs that check for you. It imports nothing from the generator and reads files only.
module.exports = function (t) {
  const { ok, eq, fs, path, REPO_ROOT } = t;
  const INDEX = 'agents/index';
  const GENERATOR = 'agents/tools/build-index.mjs';
  const REBUILD = ' — run npm run agents:index';
  const abs = (rel) => path.join(REPO_ROOT, rel);
  const read = (rel) => fs.readFileSync(abs(rel), 'utf8');
  const escapeRe = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

  t.section('agents/index: the generated code index is present, stamped, and points at real lines');

  ok(fs.existsSync(abs(GENERATOR)), GENERATOR + ' exists');
  let parses = false;
  try { require('child_process').execFileSync(process.execPath, ['--check', abs(GENERATOR)], { stdio: ['ignore', 'ignore', 'pipe'] }); parses = true; } catch (e) { parses = false; }
  ok(parses, GENERATOR + ' parses (node --check)');
  const scripts = JSON.parse(read('package.json')).scripts || {};
  eq([scripts['agents:index'], scripts['agents:check']], ['node ' + GENERATOR, 'node ' + GENERATOR + ' --check'],
    'package.json: agents:index writes the index, agents:check reports a stale one');

  // Every file the generator promises, plus one symbols file per shipped script.
  const scriptsIndexed = fs.readdirSync(abs('js')).filter((f) => f.endsWith('.js')).sort().concat(['native-bridge.js', 'sw.js']);
  const expected = ['README.md', 'pure-blocks.md', 'events.md', 'storage-keys.md', 'globals.md', 'api-calls.md', 'css-sections.md',
    'dom-ids.md', 'tests.md', 'swift.md'].concat(scriptsIndexed.map((f) => 'symbols/' + f + '.md'));
  const missing = expected.filter((f) => !fs.existsSync(abs(INDEX + '/' + f)));
  eq(missing, [], 'every index file exists (a symbols file for each js/*.js, native-bridge.js and sw.js)' + REBUILD);

  // The ONE header line: which commit (or "working tree") the file was built from. Nothing else in a file may date it.
  const HEADER = /^> Generated by agents\/tools\/build-index\.mjs from (`[0-9a-f]{7,40}`|working tree \(uncommitted changes on top of `[0-9a-f]{7,40}`\)|an unversioned copy \(not a git checkout\))\. /;
  const unstamped = expected.filter((f) => !missing.includes(f)).filter((f) => {
    const lines = read(INDEX + '/' + f).split('\n');
    return lines.filter((l) => l.startsWith('> Generated by ')).length !== 1 || !lines.slice(0, 6).some((l) => HEADER.test(l));
  });
  eq(unstamped, [], 'every index file carries exactly one "Generated by … from <commit>" header line, near its top' + REBUILD);

  // Ten symbols a reader is likely to look up first. Found in whichever symbols file lists them; the source path is that
  // file's own first line ("# js/app.js — symbols").
  const SYMBOLS = ['bookClass', 'submitBooking', '_bookingHorizon', 'renderMyBookings', 'PsycleClassColours', '_profileFrom',
    'planWeeklyTemplate', '_pillCoversBook', 'syncAllBookingsToCalendar', '_spotSuggestion'];
  const symbolFiles = expected.filter((f) => f.startsWith('symbols/') && !missing.includes(f)).map((f) => {
    const lines = read(INDEX + '/' + f).split('\n');
    const src = /^# (\S+) — symbols$/.exec(lines[0] || '');
    return { file: f, source: src ? src[1] : null, lines };
  });
  eq(symbolFiles.filter((s) => !s.source || !fs.existsSync(abs(s.source))).map((s) => s.file), [],
    'every symbols file names its source on line 1, and that source exists' + REBUILD);

  const stale = [];
  SYMBOLS.forEach((name) => {
    const entry = new RegExp('^L(\\d+)  (?:\\(iife\\) |async |class |const |let |var )?(?:async )?(?:window\\.|globalThis\\.|self\\.|root\\.)?' + escapeRe(name) + '(?![\\w$])');
    const hits = [];
    symbolFiles.forEach((s) => s.lines.forEach((l) => { const m = entry.exec(l); if (m && s.source) hits.push({ file: s.file, source: s.source, line: Number(m[1]) }); }));
    if (!hits.length) { ok(false, name + ' is listed in ' + INDEX + '/symbols/ with a line number' + REBUILD); return; }
    const wrong = hits.filter((h) => {
      const srcLine = read(h.source).split('\n')[h.line - 1];
      return typeof srcLine !== 'string' || srcLine.indexOf(name) === -1;
    });
    ok(true, name + ' is listed with a line number');
    if (wrong.length) stale.push(name + ' (' + wrong.map((h) => h.source + ':' + h.line).join(', ') + ')');
  });
  // ADVISORY, never a failure: an index that has merely drifted (someone edited a file and did not rebuild) still gets a
  // reader to the right neighbourhood, and a red test for a documentation aid would punish every ordinary edit to
  // js/app.js. `npm run agents:check` is the strict check; CI runs it as a non-blocking step.
  if (stale.length) console.log('  [advisory] agents/index/ has drifted for: ' + stale.join('; ') + REBUILD);
};
